  display: block;
  padding: 1.375rem 1.875rem 1.875rem;
  background-color: #FFFFFF;
  border-top: 2px solid #D7192D;
}
.ibe-quick-links__columns {
  display: flex;
}
.ibe-quick-links__mt {
  margin-top: 1.875rem;
}
.ibe-quick-links__mb {
  margin-bottom: 0.625rem;
}
.ibe-quick-links__list {
  padding: 0 4.0625rem 0 3.4375rem;
  font-size: 0;
}
.ibe-quick-links__list--column {
  width: 100%;
  width: 100%;
  display: flex;
  flex-direction: column;
}
.ibe-quick-links__item {
  max-width: 75%;
  vertical-align: top;
  padding: 0.9375rem 0 0 0.625rem;
}
.ibe-quick-links__title {
  position: relative;
  font-family: "iberiaheadline";
  color: #D7192D;
  font-size: 1.625rem;
  line-height: 32px;
  padding-right: 2.5rem;
}
.ibe-quick-links__title:before {
  position: absolute;
  top: 0;
  right: 0;
  font-size: 1.75rem;
}
.ibe-quick-links__title.icon-vuelos:before {
  transform: rotate(33deg);
}
.ibe-quick-links__direct-link {
  position: absolute;
  top: 0;
  right: 0;
  text-indent: -999rem;
  width: 2.5rem;
  height: 100%;
}
.ibe-quick-links__direct-link:before {
  position: absolute;
  top: 0.0625rem;
  right: 0;
  text-indent: 0;
  font-size: 1.75rem;
}
.ibe-quick-links__direct-link:hover, .ibe-quick-links__direct-link:focus {
  color: #a90e1f;
}
.ibe-quick-links__direct-link:focus {
  outline: 1px solid #FCD100;
}
.ibe-quick-links__link {
  position: relative;
  display: inline-block;
  padding-left: 1.0625rem;
  text-align: left;
}
.ibe-quick-links__link.link__regular, .ibe-quick-links__link.ibe-box-work__item-link {
  line-height: 20px;
}
.ibe-quick-links__link:before {
  content: "";
  position: absolute;
  top: 0.375rem;
  left: 0;
  display: block;
  width: 0.5rem;
  height: 0.5rem;
  background-color: #D7192D;
}
.ibe-quick-links--destiny {
  margin-top: 0px !important;
  margin-bottom: 2rem !important;
}
.ibe-quick-links--destiny {
  padding: 2.5rem 2rem;
  border-top: none;
}
.ibe-quick-links--destiny h2 {
  font-size: 1.625rem;
  color: #333333;
}
.ibe-quick-links--destiny ul {
  padding: 0;
}
.ibe-quick-links--destiny ul li {
  padding-left: 0;
}
.ibe-quick-links--destiny ul li .link__regular, .ibe-quick-links--destiny ul li .ibe-box-work__item-link {
  padding-left: 0.75rem;
  font-size: 13px;
  color: #333333;
  text-decoration: underline;
}
.ibe-quick-links--destiny ul li .link__regular:before, .ibe-quick-links--destiny ul li .ibe-box-work__item-link:before {
  top: 0.475rem;
  width: 0.25rem;
  height: 0.25rem;
}

button.ibe-quick-links__link {
  border: 0;
  background: none;
}
button.ibe-quick-links__link:hover {
  text-decoration: underline;
}

