-----------------------------------------------------------------*/
.ibe-switch {
  display: inline-block;
  width: 100%;
}
.ibe-switch__container {
  background-color: transparent;
  position: relative;
  display: inline-block;
  vertical-align: middle;
}
.ibe-switch__container--big {
  margin-top: 0.0625rem;
  width: 100%;
  height: 2.5rem;
  border-radius: 1.25rem;
}
.ibe-switch__container--big-separate {
  height: 2rem;
}
.ibe-switch__container--small {
  width: 2.5rem;
  height: 1.5rem;
  border-radius: 0.75rem;
}
.ibe-switch__label {
  font-size: 0.9375rem;
}
.ibe-switch__label:before {
  content: "\e93e";
  font-family: "iberia";
  color: #a8191a;
  position: absolute;
  top: 0;
  left: 0.1875rem;
  font-size: 1.0625rem;
}
.ibe-switch__label:after {
  content: "\e92c";
  font-family: "iberia";
  color: #666666;
  position: absolute;
  top: 0.125rem;
  right: 0.625rem;
  width: 0.53125rem;
  height: 0.53125rem;
}
.ibe-switch__label-big {
  font-family: "verdana";
  font-size: 0.75rem;
  cursor: pointer;
  width: 100%;
  height: 100%;
  border: solid 1px #CCCCCC;
  border-radius: 1.25rem;
}
.ibe-switch__label-big--stopover {
  border: none;
}
.ibe-switch__label-big:before {
  content: attr(data-txt-check);
  position: absolute;
  text-align: center;
  transition: color 0.4s ease;
  color: #333333;
  left: 0;
  width: 50%;
  top: 0;
  line-height: 40px;
  z-index: 1;
  text-overflow: ellipsis;
  white-space: nowrap;
  overflow: hidden;
  padding: 0 0.3125rem;
}
.ibe-switch__label-big--stopover:before {
  background-color: #DDDDDD;
  border-radius: 1.25rem;
  left: -16px;
  line-height: 2rem;
}
.ibe-switch__label-big:after {
  content: attr(data-txt-uncheck);
  position: absolute;
  text-align: center;
  transition: color 0.4s ease;
  color: #FFFFFF;
  right: 0;
  width: 50%;
  top: 0;
  line-height: 40px;
  z-index: 1;
  text-overflow: ellipsis;
  white-space: nowrap;
  overflow: hidden;
  padding: 0 0.3125rem;
}
.ibe-switch__label-big--stopover:after {
  line-height: 2rem;
}
.ibe-switch__checkbox {
  opacity: 0;
  width: 0;
  height: 0;
}
.ibe-switch__checkbox.focus + .ibe-switch__slider {
  border-color: #F08400;
}
.ibe-switch__slider {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  transition: 0.4s;
  border: solid 1px #CCCCCC;
  border-radius: 2.125rem;
  z-index: 1;
}
.ibe-switch__slider:before {
  position: absolute;
  content: "";
  height: 1rem;
  width: 1rem;
  left: 0.25rem;
  bottom: 0.1875rem;
  background-color: #666666;
  transition: 0.4s;
  border-radius: 50%;
}
.ibe-switch__slider-big {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  transition: 0.4s;
  border-radius: 2.125rem;
  z-index: 0;
}
.ibe-switch__slider-big:before {
  position: absolute;
  content: "";
  width: 50%;
  height: 100%;
  bottom: 0;
  left: 0;
  border-radius: 1.25rem;
  background-color: #a8191a;
  transition: 0.4s;
  transform: translateX(100%);
}
.ibe-switch__checkbox:checked + .ibe-switch__slider:before {
  background-color: #a8191a;
  transform: translateX(14px);
}
.ibe-switch__checkbox:checked ~ .ibe-switch__slider-big:before {
  transform: translateX(0%);
}
.ibe-switch__checkbox--stopover:checked ~ .ibe-switch__slider-big--stopover:before {
  left: -16px;
}
.ibe-switch__checkbox:checked + .ibe-switch__label-big:before {
  transition: color 0.4s ease;
  color: #FFFFFF;
}
.ibe-switch__checkbox:checked + .ibe-switch__label-big:after {
  transition: color 0.4s ease;
  color: #333333;
}
.ibe-switch__checkbox--stopover:checked + .ibe-switch__label-big:before {
  background-color: transparent;
}
.ibe-switch__checkbox--stopover:checked + .ibe-switch__label-big:after {
  background-color: #DDDDDD;
  border-radius: 1.25rem;
}

[data-focusin].focus + .ibe-switch__label-big {
  border: 1px solid #F08400;
  border-radius: 20px;
}

